def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells:
        return [row[:] for row in grid]

    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)

    def mirror(i, n):
        return (31 - i) % n

    out = []
    for r in range(r0, r1 + 1):
        row = []
        for c in range(c0, c1 + 1):
            rr, cc = mirror(r, h), c
            value = grid[rr][cc] if grid[rr][cc] != 8 else None

            if value is None:
                mc = mirror(c, w)
                if grid[rr][mc] != 8:
                    value = grid[rr][mc]

            if value is None:
                # If the reflection lands back inside the covered area, use
                # the closest matching visible row to extend its pattern.
                best = None
                for sr in range(h):
                    if r0 <= sr <= r1:
                        continue
                    score = sum(
                        grid[sr][x] == grid[rr][x]
                        for x in range(w)
                        if not (c0 <= x <= c1)
                    )
                    key = (score, -abs(sr - rr))
                    if best is None or key > best[0]:
                        best = (key, sr)
                if best is not None:
                    value = grid[best[1]][c]
                else:
                    # Neighboring rows often share the repeated central edge.
                    neighbors = []
                    for sr in (r0 - 1, r1 + 1):
                        if 0 <= sr < h and grid[sr][c] != 8:
                            neighbors.append(grid[sr][c])
                    value = max(set(neighbors), key=neighbors.count) if neighbors else 0

            row.append(value)
        out.append(row)
    return out
